old='''    String centralOwnerToken(){String t=prefs.getString("central.ownerToken","");if(t.length()>=32)return t;t=UUID.randomUUID().toString()+UUID.randomUUID().toString();prefs.edit().putString("central.ownerToken",t).apply();return t;}\n    String centralUploadAsset(String token,String key,String value)throws Exception{InputStream in=centralOpenLocal(value);if(in==null)return null;byte[] data=centralReadBytes(in);String mime=centralMime(value);String ext=mime.contains("png")?".png":mime.contains("webp")?".webp":mime.contains("jpeg")?".jpg":mime.contains("ttf")?".ttf":mime.contains("otf")?".otf":mime.contains("mpeg")?".mp3":mime.contains("ogg")?".ogg":".bin";JSONObject q=new JSONObject();q.put("token",token);q.put("name","asset_"+Math.abs(key.hashCode())+ext);q.put("contentType",mime);q.put("content",android.util.Base64.encodeToString(data,android.util.Base64.NO_WRAP));return centralHttp("POST","/api/asset",q).optString("path","");}\n    JSONObject buildCentralPayload(String token)throws Exception{JSONObject payload=new JSONObject(),vals=new JSONObject(),assets=new JSONObject();for(Map.Entry<String,?>e:prefs.getAll().entrySet()){String k=e.getKey();if(!centralPrefKey(k))continue;Object v=e.getValue();if(v instanceof String){String sv=(String)v;InputStream test=null;try{test=centralOpenLocal(sv);}catch(Exception ignored){}if(test!=null){try{test.close();}catch(Exception ignored){}String path=centralUploadAsset(token,k,sv);if(path!=null&&!path.isEmpty()){assets.put(k,path);continue;}}}vals.put(k,centralTyped(v));}payload.put("prefs",vals);payload.put("assets",assets);payload.put("beheshti",beheshtiEntries());payload.put("schema",1);return payload;}\n    void showCentralPublisher(){ScrollView sc=scrollPage("انتشار مرکزی");LinearLayout b=body(sc);addCard(b,text("همین طراحی و محتوایی که خودتان در پنل مخفی تنظیم کرده‌اید، منبع اصلی همه نسخه‌ها می‌شود. ظاهر فعلی اپ تغییر نمی‌کند و تنظیمات شخصی کاربران مثل موقعیت، اعلان و ذکرشمار دست‌نخورده می‌ماند.",15,textColor(),true));addCard(b,text("نسخه مرکزی دریافت‌شده: "+prefs.getInt("central.version",0),13,textColor(),false));Button pub=button("انتشار همین تغییرات برای همه");pub.setOnClickListener(v->centralPublishAsync());b.addView(pub,new LinearLayout.LayoutParams(-1,dp(58)));Button sync=smallButton("دریافت دوباره نسخه مرکزی");sync.setOnClickListener(v->centralSyncAsync(true));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,dp(52));lp.setMargins(0,dp(8),0,0);b.addView(sync,lp);}\n    void centralPublishAsync(){toast("در حال انتشار...");new Thread(()->{try{String token=centralOwnerToken();JSONObject st=centralHttp("GET","/api/config",null);if(!st.optBoolean("published",false)){JSONObject claim=new JSONObject();claim.put("token",token);claim.put("payload",new JSONObject());centralHttp("POST","/api/claim",claim);}JSONObject payload=buildCentralPayload(token);JSONObject req=new JSONObject();req.put("token",token);req.put("payload",payload);JSONObject r=centralHttp("POST","/api/publish",req);int ver=r.optInt("version",prefs.getInt("central.version",0)+1);prefs.edit().putInt("central.version",ver).apply();runOnUiThread(()->{toast("برای همه منتشر شد — نسخه "+ver);showCentralPublisher();});}catch(Exception e){runOnUiThread(()->toast("انتشار مرکزی انجام نشد"));}}).start();}\n'''
assert old in s
new=r'''    String centralOwnerToken(){String t=prefs.getString("central.ownerToken","");if(t.length()>=32)return t;t=UUID.randomUUID().toString()+UUID.randomUUID().toString();prefs.edit().putString("central.ownerToken",t).apply();return t;}
    String centralPinHash()throws Exception{String pin=prefs.getString("admin.pin","");if(pin.length()<4)throw new IOException("admin_pin_missing");java.security.MessageDigest md=java.security.MessageDigest.getInstance("SHA-256");byte[] d=md.digest(("nadaye-beheshti-owner:"+pin).getBytes("UTF-8"));StringBuilder z=new StringBuilder();for(byte x:d)z.append(String.format(Locale.US,"%02x",x&255));return z.toString();}
    void ensureCentralOwner(String token,String pinHash)throws Exception{JSONObject st=centralHttp("GET","/api/owner-status",null);if(!st.optBoolean("claimed",false)){JSONObject q=new JSONObject();q.put("token",token);q.put("pinHash",pinHash);q.put("payload",new JSONObject());centralHttp("POST","/api/claim",q);return;}if(st.optBoolean("pinBound",false))return;JSONObject q=new JSONObject();q.put("token",token);q.put("pinHash",pinHash);try{centralHttp("POST","/api/owner/bind",q);}catch(Exception bindErr){centralHttp("POST","/api/owner/recover-legacy",q);}}
    String centralUploadAsset(String token,String pinHash,String key,String value)throws Exception{InputStream in=centralOpenLocal(value);if(in==null)return null;byte[] data=centralReadBytes(in);String mime=centralMime(value);String ext=mime.contains("png")?".png":mime.contains("webp")?".webp":mime.contains("jpeg")?".jpg":mime.contains("ttf")?".ttf":mime.contains("otf")?".otf":mime.contains("mpeg")?".mp3":mime.contains("ogg")?".ogg":".bin";JSONObject q=new JSONObject();q.put("token",token);q.put("pinHash",pinHash);q.put("name","asset_"+Math.abs(key.hashCode())+ext);q.put("contentType",mime);q.put("content",android.util.Base64.encodeToString(data,android.util.Base64.NO_WRAP));return centralHttp("POST","/api/asset",q).optString("path","");}
    JSONObject buildCentralPayload(String token,String pinHash)throws Exception{JSONObject payload=new JSONObject(),vals=new JSONObject(),assets=new JSONObject();for(Map.Entry<String,?>e:prefs.getAll().entrySet()){String k=e.getKey();if(!centralPrefKey(k))continue;Object v=e.getValue();if(v instanceof String){String sv=(String)v;InputStream test=null;try{test=centralOpenLocal(sv);}catch(Exception ignored){}if(test!=null){try{test.close();}catch(Exception ignored){}String path=centralUploadAsset(token,pinHash,k,sv);if(path!=null&&!path.isEmpty()){assets.put(k,path);continue;}}}vals.put(k,centralTyped(v));}payload.put("prefs",vals);payload.put("assets",assets);payload.put("beheshti",beheshtiEntries());payload.put("schema",2);payload.put("publishedFrom","owner-panel");return payload;}
    String centralFriendlyError(Exception e){String m=String.valueOf(e.getMessage());if(m.contains("401")||m.contains("unauthorized"))return "مالکیت مرکزی تأیید نشد؛ دوباره از همین پنل تلاش کنید.";if(m.contains("recovery_locked"))return "مرکز قبلاً با مالک دیگری قفل شده است.";if(m.contains("asset_too_large"))return "یکی از فایل‌ها بیشتر از ۲۰ مگابایت است.";if(m.contains("UnknownHost")||m.contains("connect")||m.contains("timeout"))return "اتصال به سرور مرکزی برقرار نشد.";return "خطا: "+m;}
    void showCentralPublisher(){ScrollView sc=scrollPage("انتشار مرکزی واقعی");LinearLayout b=body(sc);addCard(b,text("هر تغییری که شما در همین پنل مخفی ذخیره کرده‌اید، با دکمه زیر به نسخه عمومی تبدیل می‌شود. پس از نشر، سرور دوباره خوانده می‌شود تا موفقیت واقعی تأیید شود.",15,textColor(),true));String ok=prefs.getString("central.lastPublish","");String er=prefs.getString("central.lastError","");String status="نسخه مرکزی این گوشی: "+prefs.getInt("central.version",0);if(!ok.isEmpty())status+="\nآخرین نشر موفق: "+ok;if(!er.isEmpty())status+="\nآخرین خطا: "+er;addCard(b,text(status,14,er.isEmpty()?green():Color.RED,false));Button pub=button("انتشار و تأیید همین طراحی برای همه");pub.setOnClickListener(v->centralPublishAsync());b.addView(pub,new LinearLayout.LayoutParams(-1,dp(62)));Button sync=smallButton("آزمایش: دریافت نسخه‌ای که مردم می‌بینند");sync.setOnClickListener(v->centralSyncAsync(true));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,dp(54));lp.setMargins(0,dp(8),0,0);b.addView(sync,lp);}
    void centralPublishAsync(){prefs.edit().remove("central.lastError").apply();toast("در حال ارسال طراحی شما...");new Thread(()->{try{String token=centralOwnerToken(),pinHash=centralPinHash();ensureCentralOwner(token,pinHash);JSONObject payload=buildCentralPayload(token,pinHash);JSONObject req=new JSONObject();req.put("token",token);req.put("pinHash",pinHash);req.put("payload",payload);JSONObject r=centralHttp("POST","/api/publish",req);int ver=r.optInt("version",0);if(ver<=0)throw new IOException("bad_version");JSONObject check=centralHttp("GET","/api/config",null);JSONObject remotePayload=check.optJSONObject("payload");if(check.optInt("version",0)!=ver||remotePayload==null||remotePayload.optInt("schema",0)<2)throw new IOException("server_verification_failed");String when=new java.text.SimpleDateFormat("HH:mm  yyyy/MM/dd",Locale.US).format(new Date());prefs.edit().putInt("central.version",ver).putString("central.lastPublish",when+" — نسخه "+ver).remove("central.lastError").apply();runOnUiThread(()->{toast("نشر مرکزی تأیید شد — نسخه "+ver);showCentralPublisher();});}catch(Exception e){String msg=centralFriendlyError(e);prefs.edit().putString("central.lastError",msg).apply();runOnUiThread(()->{toast("نشر نشد؛ دلیل در همین صفحه نوشته شد");showCentralPublisher();});}}).start();}
'''
s=s.replace(old,new,1)

