old_sync='''    void centralSyncAsync(boolean force){new Thread(()->{try{JSONObject cfg=centralHttp("GET","/api/config",null);if(!cfg.optBoolean("published",false))return;int remote=cfg.optInt("version",0),local=prefs.getInt("central.version",0);boolean owner=prefs.getString("central.ownerToken","").length()>=32;if(!force&&owner&&remote<=local)return;JSONObject payload=cfg.optJSONObject("payload");if(payload==null)return;JSONObject vals=payload.optJSONObject("prefs");SharedPreferences.Editor ed=prefs.edit();if(vals!=null){Iterator<String>it=vals.keys();while(it.hasNext()){String k=it.next();JSONObject tv=vals.optJSONObject(k);if(tv!=null)applyCentralTyped(ed,k,tv);}}ed.apply();JSONObject assets=payload.optJSONObject("assets");if(assets!=null){Iterator<String>it=assets.keys();while(it.hasNext()){String k=it.next(),sp=assets.optString(k,"");if(sp.isEmpty())continue;try{File f=centralDownloadAsset(k,sp);String v=(k.startsWith("spiritual.audio.")||k.startsWith("adhan.slot."))?Uri.fromFile(f).toString():f.getAbsolutePath();prefs.edit().putString(k,v).apply();}catch(Exception ignored){}}}JSONArray bh=payload.optJSONArray("beheshti");if(bh!=null)saveBeheshtiEntries(bh);prefs.edit().putInt("central.version",remote).apply();runOnUiThread(()->{if(atHome)showHome();if(force)toast("نسخه مرکزی دریافت شد");});}catch(Exception ignored){}}).start();}\n'''
assert old_sync in s
new_sync=r'''    void centralSyncAsync(boolean force){new Thread(()->{try{JSONObject cfg=centralHttp("GET","/api/config",null);if(!cfg.optBoolean("published",false)){if(force)runOnUiThread(()->toast("هنوز نسخه مرکزی منتشر نشده"));return;}int remote=cfg.optInt("version",0),local=prefs.getInt("central.version",0);boolean owner=prefs.getString("central.ownerToken","").length()>=32;if(!force&&owner&&remote<=local)return;JSONObject payload=cfg.optJSONObject("payload");if(payload==null)throw new IOException("empty_remote_payload");JSONObject vals=payload.optJSONObject("prefs");SharedPreferences.Editor ed=prefs.edit();if(vals!=null){Iterator<String>it=vals.keys();while(it.hasNext()){String k=it.next();JSONObject tv=vals.optJSONObject(k);if(tv!=null)applyCentralTyped(ed,k,tv);}}ed.apply();JSONObject assets=payload.optJSONObject("assets");if(assets!=null){Iterator<String>it=assets.keys();while(it.hasNext()){String k=it.next(),sp=assets.optString(k,"");if(sp.isEmpty())continue;try{File f=centralDownloadAsset(k,sp);String v=(k.startsWith("spiritual.audio.")||k.startsWith("adhan.slot."))?Uri.fromFile(f).toString():f.getAbsolutePath();prefs.edit().putString(k,v).apply();}catch(Exception ignored){}}}JSONArray bh=payload.optJSONArray("beheshti");if(bh!=null)saveBeheshtiEntries(bh);prefs.edit().putInt("central.version",remote).apply();runOnUiThread(()->{if(atHome)showHome();if(force)toast("همان نسخه عمومی دریافت شد — "+remote);});}catch(Exception e){if(force){String msg=centralFriendlyError(e);prefs.edit().putString("central.lastError",msg).apply();runOnUiThread(()->toast("دریافت مرکزی ناموفق بود"));}}}).start();}
'''
s=s.replace(old_sync,new_sync,1)

